    INDEX_DTYPE : tl.constexpr = tl.int32
    A = arg_A
    B = arg_B

    M = 9000
    N = 40
    K = 144
    if M * N == 0:
        # early exit due to zero-size input(s)
        return
    stride_am = 144
    stride_ak = 1
    stride_bk = 1
    stride_bn = 144

